from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    # Build the trie of banned strings
    goto = [{}]
    bad = [False]
    for word in banned:
        cur = 0
        for ch in word:
            if ch not in goto[cur]:
                goto[cur][ch] = len(goto)
                goto.append({})
                bad.append(False)
            cur = goto[cur][ch]
        bad[cur] = True

    m = len(goto)
    k = len(alphabet)
    fail = [0] * m
    delta = [[0] * k for _ in range(m)]

    # BFS: failure links, full transition table, and propagated "bad" flags
    queue = deque([0])
    while queue:
        u = queue.popleft()
        for i, ch in enumerate(alphabet):
            if ch in goto[u]:
                v = goto[u][ch]
                fail[v] = delta[fail[u]][i] if u else 0
                bad[v] = bad[v] or bad[fail[v]]
                delta[u][i] = v
                queue.append(v)
            else:
                delta[u][i] = delta[fail[u]][i] if u else 0

    # Transition matrix over automaton states, skipping bad states
    M = [[0] * m for _ in range(m)]
    for u in range(m):
        if bad[u]:
            continue
        for i in range(k):
            v = delta[u][i]
            if not bad[v]:
                M[u][v] += 1

    def vec_mul(vec, A):
        res = [0] * m
        for i, x in enumerate(vec):
            if x:
                row = A[i]
                for j in range(m):
                    res[j] = (res[j] + x * row[j]) % MOD
        return res

    def mat_mul(A, B):
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            Ri = res[i]
            for t in range(m):
                a = A[i][t]
                if a:
                    Bt = B[t]
                    for j in range(m):
                        Ri[j] = (Ri[j] + a * Bt[j]) % MOD
        return res

    # Exponentiate: start from the root state and apply M^n
    vec = [0] * m
    vec[0] = 1
    while n:
        if n & 1:
            vec = vec_mul(vec, M)
        n >>= 1
        if n:
            M = mat_mul(M, M)

    return sum(vec) % MOD
